        mapping = self._get_color_mapping(inp1, out1)
        if mapping is not None:
            # Verify on second example
            verified = self._verify_mapping(inp2, out2, mapping)
            if verified:
                return self._apply_mapping(inp2, mapping)

        return None

    def _get_color_mapping(self, inp, out):
        """Extract color/value mapping from inp->out."""
        mapping = {}
        unique_in = np.unique(inp)
        unique_out = np.unique(out)

        for val_in in unique_in:
            positions = np.where(inp == val_in)[0]
            for pos in positions:
                val_out = out[pos]
                if val_out not in mapping.values():
                    mapping[val_in] = val_out
                    break

        return mapping

    def _verify_mapping(self, inp, out, mapping):
        """Verify mapping applies correctly."""
        predicted = inp.copy().astype(float)
        for old_val, new_val in mapping.items():
            predicted[predicted == old_val] = new_val
        return np.allclose(predicted, out, atol=1e-6)

    def _apply_mapping(self, grid, mapping):
        """Apply value mapping to grid."""
        result = grid.copy()
        for old_val, new_val in mapping.items():
            result[result == old_val] = new_val
        return result

    def _object_motion_solver(self):
        """Solve based on object motion patterns."""
        if len(self.train) < 2:
            return None

        # Detect moving objects
        for i in range(1, len(self.train)):
            _, prev_out = self.train[i-1]
            curr_inp, curr_out = self.train[i]

            motion = self._compute_motion(prev_out, curr_inp)
            if motion is not None:
                predicted = self._predict_motion(curr_inp, motion)
                if predicted is not None:
                    return predicted

    def _compute_motion(self, prev, curr):
        """Compute motion of objects between frames."""
        if prev.shape != curr.shape:
            return None

        # Find connected components (objects)
        objects = self._find_objects(prev)
        if not objects:
            return None

        motion = []
        for obj_id, obj_data in objects.items():
            center_prev = obj_data['center']
            positions_curr = obj_data.get('positions_curr', [])
            if positions_curr:
                center_curr = np.mean(positions_curr, axis=0)
                diff = center_curr - center_prev
                if np.all(diff == 0):
                    motion.append({'id': obj_id, 'type': 'static'})
                elif np.allclose(diff, np.array([1, 0])):
                    motion.append({'id': obj_id, 'type': 'down'})
                elif np.allclose(diff, np.array([-1, 0])):
                    motion.append({'id': obj_id, 'type': 'up'})
                elif np.allclose(diff, np.array([0, 1])):
                    motion.append({'id': obj_id, 'type': 'right'})
                elif np.allclose(diff, np.array([0, -1])):
                    motion.append({'id': obj_id, 'type': 'left'})

        return motion if motion else None

    def _find_objects(self, grid):
        """Find connected component objects in grid."""
        if grid.ndim < 2:
            return {}

        h, w = grid.shape

        visited = np.zeros(h * w, dtype=bool)
        objects = {}
        obj_id = 0

        for y in range(h):
            for x in range(w):
                idx = y * w + x
                if visited[idx] or grid[idx] == 0:
                    continue

                # BFS to find connected component
                positions = []
                queue = [(y, x)]

                while queue:
                    cy, cx = queue.pop(0)
                    if visited[cy * w + cx]:
                        continue
                    visited[cy * w + cx] = True

                    positions.append((cy, cx))

                    # Check 4-connected neighbors
                    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ny, nx = cy + dy, cx + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            nidx = ny * w + nx
                            if not visited[nidx] and grid[nidx] == grid[idx]:
                                queue.append((ny, nx))

                if positions:
                    center = np.mean([p for p in positions], axis=0)
                    objects[obj_id] = {'positions': positions, 'center': center}
                    obj_id += 1

        return objects

    def _predict_motion(self, grid, motions):
        """Predict next frame based on object motions."""
        h, w = grid.shape

        # Apply each motion
        for m in motions:
            if m['type'] == 'down':
                grid = np.roll(grid, 1, axis=0)
            elif m['type'] == 'up':
                grid = np.roll(grid, -1, axis=0)
            elif m['type'] == 'right':
                grid = np.roll(grid, 1, axis=1)
            elif m['type'] == 'left':
                grid = np.roll(grid, -1, axis=1)

        return grid

    def _color_mapping_solver(self):
        """Solve using color/substitution mappings."""
        if len(self.train) < 1:
            return None

        # Get mapping from first example
        inp, out = self.train[0]
        mapping = self._get_color_mapping(inp, out)

        # Apply to test if available
        if self.test:
            test_inp, _ = self.test
            return self._apply_mapping(test_inp, mapping)

        return mapping

    def _spatial_pattern_solver(self):
        """Solve based on spatial pattern recognition."""
        if len(self.train) < 2:
            return None

        # Look for symmetric/periodic patterns
        for i in range(len(self.train) - 1):
            prev_out, curr_inp = self.train[i][1], self.train[i+1][0]

            # Check for rotation
            rotated_90 = np.rot90(prev_out)
            rotated_180 = np.rot90(prev_out, 2)
            rotated_270 = np.rot90(prev_out, 3)

            for name, rot_grid in [('90°', rotated_90), ('180°', rotated_180), 
                                    ('270°', rotated_270)]:
                if np.array_equal(rot_grid, curr_inp):
                    return rot_grid

            # Check for flips
            flipped_h = np.fliplr(prev_out)
            flipped_v = np.flipud(prev_out)

            for name, flip_grid in [('H', flipped_h), ('V', flipped_v)]:
                if np.array_equal(flip_grid, curr_inp):
                    return flip_grid

        return None


def solve_arc_challenge(train_pairs, test_input):
    """Convenience function to solve an ARC challenge."""
    solver = ARCPuzzleSolver()

    for inp, out in train_pairs:
        solver.add_training_example(inp, out)

    solver.set_test_example(test_input)

    return solver.run()


