"""Enhanced ARC Puzzle Solver with advanced patterns"""

import numpy as np
from collections import Counter, defaultdict
from typing import List, Dict, Tuple, Optional

class ARCPuzzleSolverAdvanced:
    """Advanced ARC puzzle solver with multiple detection strategies."""

    def __init__(self):
        self.train = []
        self.test = None

    def add_training(self, inp, out):
        if isinstance(inp, list):
            inp = np.array(inp, dtype=int)
        if isinstance(out, list):
            out = np.array(out, dtype=int)
        self.train.append((inp, out))

    def set_test(self, test_inp):
        if isinstance(test_inp, list):
            test_inp = np.array(test_inp, dtype=int)
        self.test = test_inp

    def solve(self):
        if self.test is None:
            raise ValueError("No test input provided")

        # Try multiple solvers in order of preference
        candidates = [
            self._solve_by_color_mapping,
            self._solve_by_pattern_transformation,
            self._solve_by_object_motion,
            self._solve_by_spatial_symmetry,
            self._solve_by_row_col_operations,
            self._solve_by_frequency_analysis,
        ]

        best_solution = None
        max_score = -1

        for solver_fn in candidates:
            try:
                solution = solver_fn()
                if solution is not None:
                    score = self._compute_score(solution)
                    if score > max_score:
                        max_score = score
                        best_solution = solution
            except Exception as e:
                pass  # Try next solver

        return best_solution

    def _compute_score(self, candidate):
        """Score a solution based on consistency across training pairs."""
        if len(self.train) == 0 or candidate is None:
            return 0.0

        matches = 0
        for train_inp, train_out in self.train:
            if candidate.shape != train_out.shape:
                continue

            transformed = self._apply_candidate(candidate, train_inp)
            if transformed is not None and np.allclose(transformed, train_out):
                matches += 1

        return matches / len(self.train)

    def _apply_candidate(self, rule, grid):
        if rule.size == grid.size:
            return rule
        if isinstance(rule, dict):
            result = grid.copy()
            if 'replace' in rule:
                for old_val, new_val in rule['replace'].items():
                    result[result == old_val] = new_val
            return result
        return grid

    def _solve_by_color_mapping(self):
        """Detect value/color substitution pattern."""
        if len(self.train) < 1:
            return None

        inp, out = self.train[0]

        # Extract mapping
        mapping = {}
        unique_in = np.unique(inp)
        seen_vals = set()

        for val_in in unique_in:
            pos = np.where(inp == val_in)[0][0]
            val_out = out[pos]
            if val_out not in seen_vals:
                mapping[val_in] = val_out
                seen_vals.add(val_out)

        if self.test is not None:
            return self._apply_mapping(self.test, mapping)
        return mapping

    def _apply_mapping(self, grid, mapping):
        result = grid.copy()
        for old_val, new_val in mapping.items():
            result[result == old_val] = new_val
        return result

    def _solve_by_pattern_transformation(self):
        """Detect geometric transformation (rotation, flip)."""
        if len(self.train) < 2:
            return None

        prev_out, curr_inp = self.train[-2][1], self.train[-1][0]

        # Check all rotations and flips
        transforms = [
            ('id', np.identity_like(prev_out)),
            ('rotate_90', np.rot90(prev_out, k=1)),
            ('rotate_180', np.rot90(prev_out, k=2)),
            ('rotate_270', np.rot90(prev_out, k=3)),
            ('flip_h', np.fliplr(prev_out)),
            ('flip_v', np.flipud(prev_out)),
        ]

        for name, trans in transforms:
            if np.array_equal(trans, curr_inp):
                if self.test is not None:
                    # Apply same transform to test
                    if name == 'id':
                        return self.test
                    elif name == 'rotate_90':
                        return np.rot90(self.test, k=1)
                    elif name == 'rotate_180':
                        return np.rot90(self.test, k=2)
                    elif name == 'rotate_270':
                        return np.rot90(self.test, k=3)
                    elif name == 'flip_h':
                        return np.fliplr(self.test)
                    elif name == 'flip_v':
                        return np.flipud(self.test)
                return trans

        return None

    def _solve_by_object_motion(self):
        """Track object motion across frames."""
        if len(self.train) < 2:
            return None

        # Find objects in first frame and track their motion
        prev_out, curr_out = self.train[-2][1], self.train[-1][1]

        motion_rule = self._get_motion_rule(prev_out, curr_out)
        if motion_rule is None:
            return None

        if self.test is not None:
            return self._apply_motion_to_test(curr_out, motion_rule)
        return motion_rule

    def _get_motion_rule(self, prev, curr):
        """Extract motion rules from frame comparison."""
        diff = np.abs(prev.astype(int) - curr.astype(int))

        # Simple case: count changes by position
        h, w = prev.shape

        # Find which positions changed and how
        changes = np.where(diff > 0)

        if len(changes[0]) == 0:
            return {'type': 'no_change'}

        # Check for consistent downward motion
        shifts = [0, 1, -1]
        for shift in shifts:
            shifted = np.roll(prev, shift, axis=0)
            if np.allclose(shifted, curr):
                return {'shift': 'down' if shift > 0 else 'up', 'axis': 0}

        for shift in shifts:
