        return None

    def _apply_motion_to_test(self, last_frame, rule):
        if rule.get('type') == 'no_change':
            return last_frame
        elif rule.get('axis') == 0:
            shift = 1 if rule['shift'] == 'down' else -1
            return np.roll(last_frame, shift, axis=0)
        else:
            shift = 1 if rule['shift'] == 'right' else -1
            return np.roll(last_frame, shift, axis=1)

