        # Check for horizontal/vertical symmetry
        if np.array_equal(np.fliplr(prev_out), curr_inp):
            return {'transform': 'flip_horizontal'}
        if np.array_equal(np.flipud(prev_out), curr_inp):
            return {'transform': 'flip_vertical'}
        if np.array_equal(np.rot90(prev_out), curr_inp):
            return {'transform': 'rotate_90'}

        return None

    def _solve_by_row_col_operations(self):
        """Detect row/column-specific operations."""
