import numpy as np
from collections import Counter, defaultdict
from typing import List, Dict, Tuple, Optional, Union
from copy import deepcopy


class ARCPuzzleSolverAdvanced:
    """
    Advanced solver implementing multiple strategy combinations.

    Attributes:
        train: List of (input_array, output_array) tuples
        test: Test input array
        best_solution: Best found solution
    """

    def __init__(self):
        self.train: List[Tuple[np.ndarray, np.ndarray]] = []
        self.test: Optional[np.ndarray] = None
        self.best_solution: Optional[np.ndarray] = None

    def add_training(self, inp, out):
        """
        Add a training example.

        Args:
            inp: Input grid (list of lists or numpy array)
            out: Output grid (list of lists or numpy array)
        """
        if isinstance(inp, list):
            inp = np.array(inp, dtype=int)
        if isinstance(out, list):
            out = np.array(out, dtype=int)
        self.train.append((inp, out))

    def set_test(self, test_inp):
        """Set the test input."""
        if isinstance(test_inp, list):
            test_inp = np.array(test_inp, dtype=int)
        self.test = test_inp

    def solve(self) -> Optional[np.ndarray]:
        """
        Solve the current test puzzle using all available strategies.

        Returns:
            Solution grid or None if no solution found
        """
        if self.test is None:
            raise ValueError("No test input provided")
        if len(self.train) < 1:
            raise ValueError("At least one training example required")

        candidates = []

        # Run all solvers
        strategies = [
            ('color_substitution', self._solve_by_color_substitution),
            ('geometric_transform', self._solve_by_geometric_transform),
            ('object_motion', self._solve_by_object_motion),
            ('spatial_symmetry', self._solve_by_spatial_symmetry),
            ('frequency_analysis', self._solve_by_frequency_analysis),
            ('pattern_completion', self._solve_pattern_completion),
        ]

        for name, solver_fn in strategies:
            try:
                solution = solver_fn()
                if solution is not None:
                    score = self._compute_score(solution)
                    candidates.append((score, solution, name))
            except Exception as e:
                print(f"Strategy '{name}' failed: {e}")

        # Return best candidate
        if candidates:
            candidates.sort(key=lambda x: x[0], reverse=True)
            return candidates[0][1]
        return None

    def _compute_score(self, candidate: np.ndarray) -> float:
        """Score a candidate based on how well it explains training data."""
        if candidate is None or len(self.train) == 0:
            return 0.0

        matches = sum(1 for inp, out in self.train 
                     if np.allclose(candidate, out, equal_nan=True))
        return matches / len(self.train)

    def _apply_candidate(self, rule, grid):
        """Apply a transformation rule to a grid."""
        if isinstance(rule, dict):
            result = grid.copy()
            if 'substitute' in rule:
                for old_val, new_val in rule['substitute'].items():
                    result[result == old_val] = new_val
            return result

        if isinstance(rule, tuple) and len(rule) == 2:
            transform_type, transform_param = rule
            if transform_type == 'rotate':
                return np.rot90(grid, k=transform_param % 4)
            elif transform_type == 'flip_h':
                return np.fliplr(grid)
            elif transform_type == 'flip_v':
                return np.flipud(grid)

        return grid

    def _solve_by_color_substitution(self) -> Optional[np.ndarray]:
        """Detect simple value/color substitution pattern."""
        inp, out = self.train[0]

        mapping = {}
        seen_out_vals = set()

        for pos in range(inp.size):
            if inp[pos] != 0:
                val_in = int(inp[pos])
                val_out = int(out[pos])

                # Only map to new values
                if val_out not in seen_out_vals:
                    mapping[val_in] = val_out
                    seen_out_vals.add(val_out)

        if self.test is not None:
            transformed = self._apply_mapping(self.test, mapping)
            score = self._compute_score(transformed)

            if score > self._max_score so far():
                self._max_score = score
                self.best_solution = transformed
            return transformed
        return mapping

    def _apply_mapping(self, grid, mapping):
        """Apply value mapping to a grid."""
        result = grid.copy()
        for old_val, new_val in mapping.items():
            result[result == old_val] = new_val
        return result

    def _solve_by_geometric_transform(self) -> Optional[np.ndarray]:
        """Detect geometric transformations between frames."""
        if len(self.train) < 2:
            return None

        prev_out = self.train[-2][1]
        curr_inp = self.train[-1][0]
        shapes_match = prev_out.shape == curr_inp.shape

        if not shapes_match:
            return None

        transforms = [
            ('identity', np.identity_like(prev_out)),
            ('rotate_90', lambda g: np.rot90(g, k=1)),
            ('rotate_180', lambda g: np.rot90(g, k=2)),
            ('rotate_270', lambda g: np.rot90(g, k=3)),
            ('flip_h', np.fliplr),
            ('flip_v', np.flipud),
        ]

        for name, transform_op in transforms:
            transposed = transform_op(prev_out)
            if np.array_equal(transposed, curr_inp):
                if self.test is not None:
                    if name == 'identity':
                        return self.test
                    elif name == 'rotate_90':
                        return np.rot90(self.test, k=1)
                    elif name == 'rotate_180':
                        return np.rot90(self.test, k=2)
                    elif name == 'rotate_270':
                        return np.rot90(self.test, k=3)
                    elif name == 'flip_h':
                        return np.fliplr(self.test)
                    elif name == 'flip_v':
                        return np.flipud(self.test)
                return transposed

        return None

    def _solve_by_object_motion(self) -> Optional[np.ndarray]:
        """Track object motion across frames."""
        if len(self.train) < 2:
            return None

        prev_frame = self.train[-2][1]
        curr_frame = self.train[-1][1]

        motion_info = self._extract_motion(prev_frame, curr_frame)
        if motion_info is None:
            return None

        # Apply motion to get prediction
        predicted = deepcopy(curr_frame)
        h, w = prev_frame.shape

        for shift_row, shift_col in motion_info.get('shifts', []):
            if shift_row:
                predicted = np.roll(predicted, shift_row, axis=0)
            if shift_col:
                predicted = np.roll(predicted, shift_col, axis=1)

        if self.test is not None:
            # Try applying same transformation type
            shift_type = motion_info.get('shift_type')
            if shift_type == 'down':
                return np.roll(self.test, 1, axis=0)
            elif shift_type == 'up':
                return np.roll(self.test, -1, axis=0)
            elif shift_type == 'right':
                return np.roll(self.test, 1, axis=1)
            elif shift_type == 'left':
                return np.roll(self.test, -1, axis=1)

        return predicted

    def _extract_motion(self, prev, curr) -> Optional[Dict]:
        """Extract motion information between two frames."""
        if prev.shape != curr.shape:
            return None

        diff = np.abs(prev.astype(int) - curr.astype(int))

        # Check for uniform shifts
        for axis, direction in [(0, 1), (0, -1), (1, 1), (1, -1)]:
            shifted = np.roll(prev, direction, axis=axis)
            if np.array_equal(shifted, curr):
                return {'shift_type': ['down', 'up', 'right', 'left'][axis * 2 + direction],
                       'shifts': [[direction]]}

        return None

    def _solve_by_spatial_symmetry(self) -> Optional[np.ndarray]:
        """Detect symmetry-based solutions."""
        if len(self.train) < 2:
            return None

        prev_out = self.train[-2][1]
        curr_inp = self.train[-1][0]

        # Check symmetries
        symmetries = [
            ('horizontal_flip', np.fliplr),
            ('vertical_flip', np.flipud),
            ('diagonal_flip', lambda g: np.flipud(g[:, ::-1])),
        ]

        for name, op in symmetries:
            if np.array_equal(op(prev_out), curr_inp):
                if self.test is not None:
                    return op(self.test)
        return None

    def _solve_by_frequency_analysis(self) -> Optional[np.ndarray]:
        """Analyze frequency/pixel distribution changes."""
        if len(self.train) < 1:
            return None

        inp, out = self.train[0]

        freq_in = Counter(inp.ravel())
        freq_out = Counter(out.ravel())

        # Simple heuristic: count non-background pixels
        bg = 0
        non_bg_in = sum(v for k, v in freq_in.items() if k != bg)
        non_bg_out = sum(v for k, v in freq_out.items() if k != bg)

        # If count matches, look for positional transformation
        if non_bg_in == non_bg_out:
            positions_in = np.argwhere(inp != bg)
            positions_out = np.argwhere(out != bg)

            if len(positions_in) == len(positions_out) >= 1:
                center_in = np.mean(positions_in, axis=0)
                center_out = np.mean(positions_out, axis=0)

                diff = center_out - center_in

                # Find closest rotation angle
                angles = [np.pi/2, np.pi, np.pi*1.5, 0]
                min_angle = 0
                for angle in angles:
                    rotated_center = center_in.copy()
                    rotated_center[0] += np.cos(angle)
                    rotated_center[1] += np.sin(angle)
                    if np.allclose(rotated_center, center_out, atol=1.0):
                        min_angle = angle
                        break

                if min_angle != 0:
                    if self.test is not None:
                        return np.rot90(self.test, k=int(round(min_angle / (np.pi/2))))

        return None

    def _solve_pattern_completion(self) -> Optional[np.ndarray]:
        """Handle pattern completion puzzles."""
        if len(self.train) < 1:
            return None

        # Simple completion: fill missing parts
        inp, out = self.train[0]

        # Check if pattern can be inferred from existing cells
        result = self.test if self.test else inp
        return result


