                        rotated_center[1] -= center_in[0] + 0.5

                    if np.allclose(rotated_center, center_out, atol=1.0):
                        min_angle = angle
                        break

                if min_angle != 0:
                    if self.test is not None:
                        k = int(round(min_angle / (np.pi/2))) % 4
                        return np.rot90(self.test, k=k)

