        if self.test is None:
            raise ValueError("No test input provided")
        if len(self.train) < 1:
            raise ValueError("At least one training example required")

        candidates = []
        strategies = [
            ('single_color_mapping', self._solve_single_color_mapping),
            ('geometric_transform_seq', self._solve_geom_transform_seq),
            ('obj_motion_seq', self._solve_obj_motion_seq),
        ]

        for name, solver_fn in strategies:
            try:
                solution = solver_fn()
                if solution is not None:
                    score = self._compute_score(solution)
                    candidates.append((score, solution, name))
            except Exception:
                pass

        if candidates:
            candidates.sort(key=lambda x: x[0], reverse=True)
            return candidates[0][1]
        return None

    def _compute_score(self, candidate):
        if candidate is None or len(self.train) == 0:
            return 0.0
        return 0.5  # Placeholder for simple cases

    def _apply_mapping(self, grid, mapping):
        result = grid.copy()
        for old_val, new_val in mapping.items():
            result[result == old_val] = new_val
        return result

    def _solve_single_color_mapping(self):
        """Single example color/value mapping."""
        if len(self.train) < 1:
            return None
        prev_frame, curr_frame = self.train[0]
        mapping = {}
        seen_vals = set()

        for pos in range(prev_frame.size):
            if prev_frame[pos] != 0:
                val_in = int(prev_frame[pos])
                val_out = int(curr_frame[pos])
                if val_out not in seen_vals:
                    mapping[val_in] = val_out
                    seen_vals.add(val_out)

        if self.test is not None:
            transformed = self._apply_mapping(self.test, mapping)
            return transformed
        return mapping

    def _solve_geom_transform_seq(self):
        """Detect geometric transform from sequence of frames (at least 2 pairs needed)."""
        if len(self.train) < 2:
            return None

        prev_frame = self.train[-2][1]
        curr_frame = self.train[-1][1]

        if prev_frame.shape != curr_frame.shape:
            return None

        transforms = [
            ('identity', lambda g: g.copy()),
            ('rotate_90', lambda g: np.rot90(g, k=1)),
            ('rotate_180', lambda g: np.rot90(g, k=2)),
            ('rotate_270', lambda g: np.rot90(g, k=3)),
            ('flip_h', np.fliplr),
            ('flip_v', np.flipud),
        ]

        for name, transform_op in transforms:
            transposed = transform_op(prev_frame)
            if np.array_equal(transposed, curr_frame):
                if self.test is not None:
                    return transform_op(self.test)
                return transform_op(prev_frame)

        return None

    def _solve_obj_motion_seq(self):
        """Detect object motion from sequence of frames."""
        if len(self.train) < 2:
            return None
        prev_frame = self.train[-2][1]
        curr_frame = self.train[-1][1]

        motion_info = self._extract_motion(prev_frame, curr_frame)
        if motion_info is None:
            return None

        shift_type = motion_info.get('shift_type')
        if shift_type == 'down' and self.test is not None:
            return np.roll(self.test, 1, axis=0)
        elif shift_type == 'up' and self.test is not None:
            return np.roll(self.test, -1, axis=0)
        elif shift_type == 'right' and self.test is not None:
            return np.roll(self.test, 1, axis=1)
        elif shift_type == 'left' and self.test is not None:
            return np.roll(self.test, -1, axis=1)
        return None

    def _extract_motion(self, prev, curr):
        if prev.shape != curr.shape:
            return None
        for axis, direction, type_name in [
            (0, 1, 'down'), (0, -1, 'up'),
            (1, 1, 'right'), (1, -1, 'left'),
        ]:
            shifted = np.roll(prev, direction, axis=axis)
            if np.array_equal(shifted, curr):
                return {'shift_type': type_name}
        return None


